INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation)
VALUES
('ภาษาไทย', 'ป.4', '[ท 1.1 ป.4/1] การอ่านออกเสียงบทร้อยแก้วและบทร้อยกรอง', 'easy', 'mcq', 'คำในข้อใดอ่านออกเสียงอักษรนำถูกต้อง?', '["ผลิต อ่านว่า ผะ-ลิด","ปรารถนา อ่านว่า ปราด-ถะ-หนา","ตลาด อ่านว่า ตะ-หลาด","สมาคม อ่านว่า สะ-มา-คม"]'::jsonb, 2, '"ตลาด" เป็นคำที่มีอักษรนำ (ต นำ ล) อ่านออกเสียงสองพยางค์ พยางค์หลังออกเสียงเหมือนมี ห นำ คือ ตะ-หลาด'),
('ภาษาไทย', 'ป.4', '[ท 1.1 ป.4/1] การอ่านออกเสียงคำที่มี ร ล ว ควบกล้ำ', 'easy', 'mcq', 'ข้อใดมีคำควบกล้ำแท้ทุกคำ?', '["สร้างเสริม, จริงจัง","กราบพระ, กว้างขวาง","เศรษฐี, ทรงทราบ","เสร็จสิ้น, ปราศจาก"]'::jsonb, 1, 'กราบพระ (กร), กว้างขวาง (กว) เป็นคำควบกล้ำแท้ที่ออกเสียงพยัญชนะต้นสองตัวพร้อมกัน ส่วนข้ออื่นมีคำควบไม่แท้ปนอยู่'),
('ภาษาไทย', 'ป.4', '[ท 1.1 ป.4/2] การอธิบายความหมายของคำ ประโยค และสำนวน', 'medium', 'mcq', 'สำนวน "ขี่ช้างจับตั๊กแตน" มีความหมายตรงกับข้อใด?', '["ทำงานใหญ่แต่ได้ผลประโยชน์น้อย","ทำสิ่งที่เป็นไปไม่ได้ให้สำเร็จ","มีความพยายามอย่างยิ่งยวด","ทำลายสิ่งของเพื่อประโยชน์ส่วนตัว"]'::jsonb, 0, '"ขี่ช้างจับตั๊กแตน" หมายถึง การลงทุนหรือลงแรงทำสิ่งใหญ่โตแต่ได้ผลตอบแทนเพียงเล็กน้อย ไม่คุ้มค่า'),
('ภาษาไทย', 'ป.4', '[ท 1.1 ป.4/2] การเข้าใจความหมายของคำศัพท์ในบริบท', 'medium', 'mcq', 'คำว่า "มัธยัสถ์" มีความหมายตรงข้ามกับคำในข้อใด?', '["ตระหนี่","ฟุ่มเฟือย","รอบคอบ","ประหยัด"]'::jsonb, 1, 'มัธยัสถ์ หมายถึง การใช้จ่ายอย่างประหยัดพอเหมาะ จึงมีความหมายตรงข้ามกับคำว่า "ฟุ่มเฟือย"'),
('ภาษาไทย', 'ป.4', '[ท 1.1 ป.4/3] การอ่านจับใจความจากสื่อต่างๆ', 'medium', 'mcq', '"ต้นไม้ช่วยดูดซับก๊าซคาร์บอนไดออกไซด์และคายก๊าซออกซิเจนให้สิ่งมีชีวิตใช้หายใจ นอกจากนี้รากยังช่วยยึดดินไม่ให้พังทลาย" ใจความสำคัญของข้อความนี้คืออะไร?', '["รากของต้นไม้ยึดดินได้ดี","ต้นไม้มีประโยชน์ต่อสิ่งมีชีวิตและสิ่งแวดล้อม","สิ่งมีชีวิตทุกชนิดต้องหายใจ","ก๊าซออกซิเจนเกิดจากต้นไม้เท่านั้น"]'::jsonb, 1, 'ใจความสำคัญสรุปรวมถึงประโยชน์ของต้นไม้ทั้งในด้านการให้อากาศหายใจและการช่วยยึดหน้าดิน'),
('ภาษาไทย', 'ป.4', '[ท 1.1 ป.4/4] การแยกข้อเท็จจริงและข้อคิดเห็น', 'medium', 'mcq', 'ข้อความใดต่อไปนี้เป็น "ข้อคิดเห็น"?', '["ประเทศไทยตั้งอยู่ในทวีปเอเชีย","น้ำจะเดือดที่อุณหภูมิ 100 องศาเซลเซียส","ดอกกุหลาบสีแดงเป็นดอกไม้ที่สวยงามที่สุดในโลก","ดวงอาทิตย์ขึ้นทางทิศตะวันออก"]'::jsonb, 2, 'ความสวยงามเป็นความรู้สึกส่วนบุคคล ไม่สามารถพิสูจน์ให้ทุกคนยอมรับตรงกันได้ จึงเป็นข้อคิดเห็น'),
('ภาษาไทย', 'ป.4', '[ท 1.1 ป.4/4] การแยกข้อเท็จจริงและข้อคิดเห็น', 'easy', 'mcq', 'ข้อความใดเป็น "ข้อเท็จจริง"?', '["วันนี้อากาศร้อนจนน่าหงุดหงิด","เด็กที่เล่นกีฬาเป็นคนมีน้ำใจทุกคน","จังหวัดขอนแก่นตั้งอยู่ในภาคตะวันออกเฉียงเหนือ","วิชาคณิตศาสตร์ยากกว่าวิชาภาษาไทย"]'::jsonb, 2, 'ที่ตั้งของจังหวัดขอนแก่นเป็นความจริงทางภูมิศาสตร์ที่มีหลักฐานยืนยันชัดเจน'),
('ภาษาไทย', 'ป.4', '[ท 1.1 ป.4/5] การคาดคะเนเหตุการณ์จากเรื่องที่อ่าน', 'medium', 'mcq', '"เมฆดำทมิฬลอยปกคลุมทั่วท้องฟ้า ลมพัดกรรโชกแรง ฟ้าแลบแปลบปลาบ" จากข้อความนี้จะเกิดเหตุการณ์ใดตามมา?', '["อากาศหนาวจัดจนเกิดหิมะ","ฝนกำลังจะตกหนักและอาจมีพายุ","เกิดแผ่นดินไหวรุนแรง","เกิดน้ำท่วมฉับพลันในทันที"]'::jsonb, 1, 'สัญญาณเมฆดำ ลมแรง และฟ้าแลบ เป็นสัญญาณบ่งบอกว่าฝนและพายุกำลังจะตก'),
('ภาษาไทย', 'ป.4', '[ท 1.1 ป.4/6] การสรุปความรู้และข้อคิดจากการอ่านเพื่อนำไปใช้', 'hard', 'mcq', 'นิทานเรื่อง "กระต่ายกับเต่า" ให้ข้อคิดเตือนใจเรื่องใดมากที่สุด?', '["ความคล่องแคล่วว่องไวทำให้ชนะเสมอ","ความประมาทเป็นหนทางสู่ความล้มเหลว","การเดินช้าช่วยรักษาสุขภาพ","ควรแข่งขันกับคนที่อ่อนแอกว่า"]'::jsonb, 1, 'กระต่ายแพ้เพราะประมาทและชะล่าใจ นอนหลับระหว่างทาง ส่วนเต่าชนะเพราะความเพียรพยายาม'),
('ภาษาไทย', 'ป.4', '[ท 1.1 ป.4/7] การอ่านหนังสือที่มีคุณค่าตามความสนใจ', 'easy', 'mcq', 'มารยาทในการอ่านหนังสือในห้องสมุดข้อใดถูกต้องที่สุด?', '["พูดคุยปรึกษาการบ้านกับเพื่อนเสียงดัง","นำขนมและน้ำหวานเข้าไปรับประทานขณะอ่าน","พับมุมหนังสือเพื่อทำเครื่องหมายหน้าคั่น","รักษาความเงียบและเก็บหนังสือเข้าที่ให้เรียบร้อย"]'::jsonb, 3, 'การรักษาความเงียบและการเก็บหนังสือเข้าที่เดิมเป็นมารยาทสำคัญของการใช้ห้องสมุด'),
('ภาษาไทย', 'ป.4', '[ท 1.1 ป.4/8] การมีมารยาทในการอ่าน', 'easy', 'mcq', 'หากต้องการอ่านหนังสือพิมพ์ที่ผู้อื่นกำลังอ่านอยู่ ควรทำอย่างไร?', '["ดึงมาอ่านทันทีเพราะอยากอ่านมาก","ชะโงกหน้าเข้าไปอ่านใกล้ๆ","รอให้ผู้อื่นอ่านเสร็จก่อนแล้วจึงขออ่านต่อ","หยิบหน้าอื่นที่เขายังไม่ได้เปิดมาอ่าน"]'::jsonb, 2, 'การรอให้ผู้อื่นอ่านเสร็จอย่างสุภาพเป็นมารยาทที่ดีในการอ่านร่วมกับผู้อื่น'),
('ภาษาไทย', 'ป.4', '[ท 1.1 ป.4/2] การเข้าใจความหมายของสำนวนไทย', 'medium', 'mcq', 'คนที่ไม่ยอมลงมือทำงานแต่วิพากษ์วิจารณ์คนอื่น ตรงกับสำนวนใด?', '["มือไม่พายเอาเท้าราน้ำ","น้ำขึ้นให้รีบตัก","จับปลาสองมือ","ชี้โพรงให้กระรอก"]'::jsonb, 0, '"มือไม่พายเอาเท้าราน้ำ" หมายถึง คนที่ไม่ช่วยเหลืองานแล้วยังทำตัวเกะกะขัดขวางการทำงานของผู้อื่น'),
('ภาษาไทย', 'ป.4', '[ท 2.1 ป.4/1] การคัดลายมือตัวบรรจงเต็มบรรทัดและครึ่งบรรทัด', 'easy', 'mcq', 'ข้อใดเป็นหลักการคัดลายมือตัวบรรจงที่ถูกต้อง?', '["เขียนตัวเอียงมากๆ เพื่อความสวยงาม","เขียนหัวพยัญชนะให้ชัดเจน วางสระวรรณยุกต์ตรงตำแหน่ง","เว้นวรรคช่องไฟให้ห่างมากที่สุด","ลากเส้นตวัดหางให้ยาวทับบรรทัดอื่น"]'::jsonb, 1, 'การคัดลายมือที่ถูกต้องต้องเขียนหัวตัวอักษรกลมชัดเจน วางสระและวรรณยุกต์ตรงตำแหน่งตามหลักเกณฑ์'),
('ภาษาไทย', 'ป.4', '[ท 2.1 ป.4/2] การเขียนสื่อความโดยใช้คำได้ถูกต้องชัดเจน', 'medium', 'mcq', 'ประโยคใดใช้คำลักษณนามถูกต้อง?', '["คุณพ่อซื้อช้อนมา 2 อัน","คุณแม่ซื้อแหวนทอง 1 วง","คุณครูมีดินสอ 3 ด้าม","พี่ชายกางร่ม 1 อัน"]'::jsonb, 1, 'แหวนใช้ลักษณนามว่า "วง" (ช้อนใช้ "คัน", ดินสอใช้ "แท่ง", ร่มใช้ "คัน")'),
('ภาษาไทย', 'ป.4', '[ท 2.1 ป.4/3] การเขียนแผนภาพโครงเรื่องและแผนภาพความคิด', 'medium', 'mcq', 'องค์ประกอบใด "ไม่จำเป็น" ต้องมีในแผนภาพโครงเรื่องของนิทาน?', '["ตัวละคร","สถานที่และเวลา","เหตุการณ์และผลของเหตุการณ์","ราคาจำหน่ายของหนังสือนิทาน"]'::jsonb, 3, 'แผนภาพโครงเรื่องประกอบด้วย ใคร (ตัวละคร), ที่ไหน (ฉาก/เวลา), ทำอะไร (เหตุการณ์), และผลเป็นอย่างไร ข้อคิดที่ได้ ไม่เกี่ยวกับราคาหนังสือ'),
('ภาษาไทย', 'ป.4', '[ท 2.1 ป.4/4] การเขียนย่อความจากเรื่องสั้นๆ', 'hard', 'mcq', 'ข้อใดเป็นข้อปฏิบัติที่ถูกต้องในการเขียนย่อความ?', '["คัดลอกข้อความเดิมทั้งหมดมาตัดต่อใหม่","เปลี่ยนสรรพนามบุรุษที่ 1 และ 2 เป็นบุรุษที่ 3","ใส่เครื่องหมายอัญประกาศแสดงคำพูดเดิมเสมอ","เติมความรู้สึกส่วนตัวของผู้เขียนลงไปด้วย"]'::jsonb, 1, 'การเขียนย่อความต้องเรียบเรียงด้วยสำนวนตนเอง และเปลี่ยนสรรพนามบุรุษที่ 1 และ 2 ให้เป็นบุรุษที่ 3 เสมอ'),
('ภาษาไทย', 'ป.4', '[ท 2.1 ป.4/5] การเขียนจดหมายถึงเพื่อนและบิดามารดา', 'medium', 'mcq', 'คำขึ้นต้นในการเขียนจดหมายถึงบิดามารดาที่ถูกต้องคือข้อใด?', '["สวัสดีคุณพ่อคุณแม่ที่รัก","กราบเท้าคุณพ่อคุณแม่ที่เคารพอย่างสูง","ถึงคุณพ่อคุณแม่","เรียนคุณพ่อคุณแม่ที่นับถือ"]'::jsonb, 1, 'คำขึ้นต้นจดหมายถึงบิดามารดาตามแบบแผนคือ "กราบเท้าคุณพ่อคุณแม่ที่เคารพอย่างสูง" และคำลงท้ายคือ "ด้วยความเคารพรักอย่างสูง"'),
('ภาษาไทย', 'ป.4', '[ท 2.1 ป.4/6] การเขียนบันทึกและการเขียนรายงานความรู้', 'easy', 'mcq', 'ข้อใดเป็นข้อมูลสำคัญที่ต้องระบุในการเขียนบันทึกประจำวัน?', '["ชื่อสำนักพิมพ์","วัน เดือน ปี และเวลาที่เกิดเหตุการณ์","ราคาของสมุดบันทึก","เลขบัตรประจำตัวประชาชน"]'::jsonb, 1, 'การบันทึกประจำวันต้องระบุ วัน เดือน ปี และเวลาเพื่อบันทึกลำดับเหตุการณ์ที่เกิดขึ้นจริง'),
('ภาษาไทย', 'ป.4', '[ท 2.1 ป.4/7] การเขียนเรื่องตามจินตนาการ', 'medium', 'mcq', 'สิ่งสำคัญที่สุดในการเขียนเรื่องตามจินตนาการคือข้อใด?', '["การคัดลอกเนื้อเรื่องจากภาพยนตร์ชื่อดัง","ความคิดริเริ่มสร้างสรรค์และข้อคิดที่เป็นประโยชน์","การใช้คำศัพท์ภาษาต่างประเทศให้มากที่สุด","การเขียนเรื่องที่ยาวเกิน 10 หน้ากระดาษ"]'::jsonb, 1, 'การเขียนเรื่องตามจินตนาการต้องอาศัยความคิดริเริ่มสร้างสรรค์ ความสมเหตุสมผล และมีข้อคิดสอนใจที่ดี'),
('ภาษาไทย', 'ป.4', '[ท 2.1 ป.4/8] การมีมารยาทในการเขียน', 'easy', 'mcq', 'การกระทำใดถือว่า "ไม่มีมารยาท" ในการเขียน?', '["ใช้น้ำยาลบคำผิดลบให้สะอาดเรียบร้อย","เขียนข้อความขีดเขียนบนโต๊ะเรียนและผนังห้องน้ำ","ใช้ภาษาที่สุภาพ เหมาะสมกับกาลเทศะ","ตรวจสอบความถูกต้องของตัวสะกดก่อนส่ง"]'::jsonb, 1, 'การขีดเขียนในที่สาธารณะ เช่น โต๊ะเรียน ผนังห้องน้ำ ถือเป็นการทำลายทรัพย์สินและขาดมารยาทอย่างยิ่ง'),
('ภาษาไทย', 'ป.4', '[ท 3.1 ป.4/1] การจำแนกข้อเท็จจริงและข้อคิดเห็นจากเรื่องที่ฟังและดู', 'medium', 'mcq', 'จากการฟังโฆษณา "ยาสีฟันนี้ใช้แล้วฟันขาวสะอาดใน 3 วินาที ดาราชื่อดังทุกคนเลือกใช้" ข้อใดคือข้อคิดเห็นเกินจริง?', '["ยาสีฟันเป็นของใช้ในชีวิตประจำวัน","ดาราใช้ยาสีฟันทำความสะอาดฟัน","ใช้แล้วฟันขาวสะอาดภายใน 3 วินาที","ยาสีฟันมีจำหน่ายในท้องตลาด"]'::jsonb, 2, 'การกล่าวอ้างว่าฟันขาวได้ในเวลาเพียง 3 วินาทีเป็นการโฆษณาชวนเชื่อที่เกินความเป็นจริงทางวิทยาศาสตร์'),
('ภาษาไทย', 'ป.4', '[ท 3.1 ป.4/2] การจับใจความและพูดแสดงความคิดเห็น', 'medium', 'mcq', 'เมื่อฟังเพื่อนพูดรายงานหน้าชั้นเรียน การกระทำใดเหมาะสมที่สุด?', '["นั่งหลับพักผ่อน","ตั้งใจฟังและจดบันทึกประเด็นสำคัญ","คุยล้อเลียนน้ำเสียงของเพื่อน","ลุกเดินไปมาในห้องเรียน"]'::jsonb, 1, 'การตั้งใจฟังและจดบันทึกเป็นมารยาทและทักษะที่ดีในการรับสารจากการพูดรายงาน'),
('ภาษาไทย', 'ป.4', '[ท 3.1 ป.4/3] การพูดรายงานเรื่องหรือประเด็นที่ศึกษาค้นคว้า', 'medium', 'mcq', 'ขั้นตอนแรกในการเตรียมตัวพูดรายงานหน้าชั้นเรียนคือข้อใด?', '["แต่งกายด้วยชุดแฟนซี","กำหนดหัวข้อและวางแผนค้นคว้าข้อมูล","ฝึกพูดเสียงดังตะโกน","เตรียมของแจกให้เพื่อน"]'::jsonb, 1, 'การกำหนดหัวข้อและค้นคว้าข้อมูลอย่างเป็นระบบเป็นขั้นตอนแรกที่สำคัญที่สุดในการเตรียมรายงาน'),
('ภาษาไทย', 'ป.4', '[ท 3.1 ป.4/4] การตั้งคำถามและตอบคำถามเชิงเหตุผล', 'easy', 'mcq', 'คำถามข้อใดเป็นคำถามเชิงเหตุผล?', '["วันแม่แห่งชาติตรงกับวันที่เท่าไร?","ทำไมเราจึงต้องช่วยกันประหยัดน้ำและไฟฟ้า?","ใครเป็นหัวหน้าห้อง ป.4?","เธอชอบสีอะไรมากที่สุด?"]'::jsonb, 1, 'คำถามที่ขึ้นต้นด้วย "ทำไม" ต้องการคำตอบที่อธิบายเหตุผล ผลกระทบ และความสำคัญ'),
('ภาษาไทย', 'ป.4', '[ท 3.1 ป.4/5] การพูดลำดับขั้นตอนการปฏิบัติงาน', 'medium', 'mcq', 'คำเชื่อมข้อใดเหมาะสำหรับใช้พูดลำดับขั้นตอนการทำงานมากที่สุด?', '["อย่างไรก็ตาม, แม้ว่า","ขั้นแรก, ต่อมา, จากนั้น, สุดท้าย","เพราะฉะนั้น, จึง","เช่น, ได้แก่"]'::jsonb, 1, 'คำว่า "ขั้นแรก, ต่อมา, จากนั้น, สุดท้าย" ช่วยบอกลำดับขั้นตอนก่อนหลังได้อย่างชัดเจน'),
('ภาษาไทย', 'ป.4', '[ท 3.1 ป.4/6] การมีมารยาทในการฟัง การดู และการพูด', 'easy', 'mcq', 'หากมีข้อสงสัยขณะที่วิทยากรกำลังบรรยาย ควรปฏิบัติอย่างไร?', '["ตะโกนถามแทรกขึ้นมาทันที","ยกมือขึ้นรอให้วิทยากรเปิดโอกาสให้ถามก่อน","คุยถามเพื่อนข้างๆ ให้รู้เรื่องเดี๋ยวนั้น","เดินขึ้นไปถามบนเวที"]'::jsonb, 1, 'มารยาทที่ดีคือการยกมือและรอจังหวะที่ผู้พูดอนุญาตหรือช่วงเปิดซักถามท้ายการบรรยาย'),
('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/1] อักษรสามหมู่ (ไตรยางศ์)', 'easy', 'mcq', 'พยัญชนะในข้อใดจัดเป็น "อักษรสูง" ทั้งหมด?', '["ข, ฉ, ถ, ผ, ส","ก, จ, ด, ต, บ","ค, ช, ซ, ท, พ","ง, ญ, น, ย, ม"]'::jsonb, 0, 'อักษรสูงมี 11 ตัว ได้แก่ ข ฃ ฉ ฐ ถ ผ ฝ ศ ษ ส ห (ท่องจำ: ผีฝากถุงข้าวสารให้ฉัน)'),
('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/1] อักษรกลางและการผันวรรณยุกต์', 'easy', 'mcq', 'คำในข้อใดผันเสียงวรรณยุกต์ได้ครบทั้ง 5 เสียง?', '["ไข่ (อักษรสูง)","กา (อักษรกลาง คำเป็น)","คา (อักษรต่ำ คำเป็น)","กบ (อักษรกลาง คำตาย)"]'::jsonb, 1, 'อักษรกลางที่เป็นคำเป็น เช่น "กา" สามารถผันได้ครบทั้ง 5 เสียงวรรณยุกต์ (กา ก่า ก้า ก๊า ก๋า)'),
('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/1] คำเป็นและคำตาย', 'medium', 'mcq', 'ข้อใดมีคำตายทุกคำ?', '["มด, กบ, นก, เมฆ","บ้าน, เมือง, นอน, ลม","ใจ, ดำ, ไป, มา","ดาว, เดือน, ลอย, น้ำ"]'::jsonb, 0, 'มด (กด), กบ (กบ), นก (กก), เมฆ (กก) มีตัวสะกดในแม่ กบด (กบ กบด) ซึ่งเป็นคำตายทั้งหมด'),
('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/1] มาตราตัวสะกดตรงมาตราและไม่ตรงมาตรา', 'easy', 'mcq', 'คำว่า "มงกุฎ, ปรากฏ, ตำรวจ" สะกดในมาตราใด?', '["แม่กก","แม่กด","แม่กน","แม่กบ"]'::jsonb, 1, 'ฎ, ฏ, จ ออกเสียงตัวสะกดเหมือน ด จึงจัดอยู่ในมาตราแม่กด (ไม่ตรงรูป)'),
('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/1] สระเดี่ยวและสระประสม', 'medium', 'mcq', 'คำในข้อใดใช้ "สระประสม" ทั้งหมด?', '["กิน, นอน","เสือ, เรือ, เกลือ","ตา, ยาย","เด็ก, เล็ก"]'::jsonb, 1, 'สระประสมมี 3 เสียงหลักคือ เอียะ/เอีย, เอือะ/เอือ, อัวะ/อัว (เสือ เรือ เกลือ ใช้สระเอือ)'),
('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/2] ชนิดของคำ: คำนาม', 'easy', 'mcq', 'คำนามที่ชี้เฉพาะเจาะจง (วิสามานยนาม) คือคำในข้อใด?', '["โรงเรียน","โรงเรียนบ้านคำไผ่","คุณครู","นักเรียน"]'::jsonb, 1, '"โรงเรียนบ้านคำไผ่" เป็นชื่อเฉพาะเจาะจงของโรงเรียนแห่งเดียว จัดเป็นวิสามานยนาม'),
('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/2] ชนิดของคำ: คำสรรพนาม', 'easy', 'mcq', '"ข้าพเจ้าขอขอบคุณทุกท่านที่มาร่วมงาน" คำว่า "ข้าพเจ้า" เป็นคำสรรพนามชนิดใด?', '["สรรพนามบุรุษที่ 1","สรรพนามบุรุษที่ 2","สรรพนามบุรุษที่ 3","สรรพนามชี้เฉพาะ"]'::jsonb, 0, '"ข้าพเจ้า" ใช้แทนตัวผู้พูด จึงเป็นสรรพนามบุรุษที่ 1'),
('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/2] ชนิดของคำ: คำกริยา', 'medium', 'mcq', 'ประโยคใดมี "สกรรมกริยา" (คำกริยาที่ต้องมีกรรมมารับ)?', '["น้องหัวเราะเสียงดัง","นกบินบนท้องฟ้า","ชาวนาเกี่ยวข้าวในทุ่ง","ฝนตกหนักมาก"]'::jsonb, 2, '"เกี่ยว" เป็นสกรรมกริยา เพราะต้องมีกรรมมารับคือ "ข้าว" ส่วนหัวเราะ บิน ตก ไม่ต้องมีกรรมรับ'),
('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/2] ชนิดของคำ: คำวิเศษณ์', 'medium', 'mcq', 'ในประโยค "เต่าตัวโตเดินช้ามาก" คำใดเป็นคำวิเศษณ์บอกอาการ?', '["เต่า","เดิน","ช้า","ตัวโต"]'::jsonb, 2, '"ช้า" ทำหน้าที่ขยายกริยา "เดิน" เพื่อบอกลักษณะท่าทางการเคลื่อนที่ จึงเป็นคำวิเศษณ์บอกอาการ'),
('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/3] การใช้พจนานุกรมค้นหาความหมายของคำ', 'hard', 'mcq', 'การเรียงลำดับคำตามพจนานุกรม ข้อใดเรียงได้ถูกต้อง?', '["กล้วย, กวาง, ข้าว, ไข่","ขวด, ข้าว, กล้วย, กาก","จาน, ชาม, ข้าว, ดิน","ปลา, นก, ม้า, ลิง"]'::jsonb, 0, 'พจนานุกรมเรียงตามพยัญชนะ ก-ฮ (กล้วย -> กวาง -> ข้าว -> ไข่ โดย ก มาก่อน ข)'),
('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/3] การเรียงลำดับสระในพจนานุกรม', 'hard', 'mcq', 'คำที่มีพยัญชนะต้นเหมือนกัน ข้อใดเรียงตามลำดับรูปสระในพจนานุกรมถูกต้อง?', '["กา, กะ, กิ, กี","กะ, กา, กิ, กี","กิ, กี, กะ, กา","กา, กิ, กะ, กี"]'::jsonb, 1, 'ลำดับรูปสระเริ่มจาก -ะ (วิสรรชนีย์), -า (ลากข้าง), -ิ (พินทุ์อิ), -ี (ฟันหนู) ตามลำดับ'),
('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/4] ส่วนประกอบของประโยค', 'medium', 'mcq', 'ประโยคใดมีส่วนประกอบครบ "ประธาน + กริยา + กรรม"?', '["ดวงอาทิตย์ส่องแสงเจิดจ้า","คุณแม่ทำอาหารในครัว","เด็กๆ วิ่งเล่นในสนาม","น้ำไหลรินอย่างช้าๆ"]'::jsonb, 1, 'ประธาน = คุณแม่, กริยา = ทำ, กรรม = อาหาร (ในครัว = ขยายสถานที่)'),
('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/4] ประโยค 2 ส่วน และประโยค 3 ส่วน', 'medium', 'mcq', 'ข้อใดจัดเป็น "ประโยค 2 ส่วน"?', '["แมวจับหนู","คุณครูสอนหนังสือ","ดอกมะลิส่งกลิ่นหอมฟุ้ง","พี่ชายอ่านนิทาน"]'::jsonb, 2, 'ดอกมะลิ (ประธาน) + ส่งกลิ่นหอมฟุ้ง (กริยาและขยายกริยา) ไม่มีกรรมมารับ จัดเป็นประโยค 2 ส่วน'),
('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/5] ประโยคบอกเล่า ปฏิเสธ คำถาม ขอร้อง และคำสั่ง', 'easy', 'mcq', '"กรุณาถอดรองเท้าก่อนเข้าห้องเรียน" เป็นประโยคชนิดใด?', '["ประโยคคำสั่ง","ประโยคขอร้อง","ประโยคปฏิเสธ","ประโยคบอกเล่า"]'::jsonb, 1, 'ประโยคที่มีคำว่า "กรุณา", "โปรด", "วาน" เป็นประโยคขอร้องเพื่อขอความร่วมมืออย่างสุภาพ'),
('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/6] คำราชาศัพท์สำหรับพระมหากษัตริย์และพระสงฆ์', 'medium', 'mcq', 'คำราชาศัพท์ว่า "พระเนตร" หมายถึงอวัยวะใด?', '["หู","ตา","จมูก","ปาก"]'::jsonb, 1, 'พระเนตร หมายถึง ดวงตา (พระกรรณ = หู, พระนาสิก = จมูก, พระโอษฐ์ = ปาก)'),
('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/6] คำสุภาพที่ใช้สำหรับพระสงฆ์', 'easy', 'mcq', 'คำว่า "กิน" สำหรับพระภิกษุสงฆ์ควรใช้คำใด?', '["เสวย","ฉัน","รับประทาน","จำวัด"]'::jsonb, 1, 'พระสงฆ์ใช้คำว่า "ฉัน" (เสวย ใช้กับพระมหากษัตริย์, จำวัด หมายถึง นอน)'),
('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/6] คำสุภาพในภาษาไทย', 'medium', 'mcq', 'คำสุภาพของคำว่า "ผักบุ้ง" คือคำในข้อใด?', '["ผักรู้นอน","ผักทอดยอด","ฟักเหลือง","นารีจำศีล"]'::jsonb, 1, 'ผักทอดยอด เป็นคำสุภาพของผักบุ้ง (ผักรู้นอน = ผักกระเฉด, ฟักเหลือง = ฟักทอง)'),
('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/7] สำนวน สุภาษิต และคำพังเพย', 'medium', 'mcq', 'สำนวนใดหมายถึง "การพูดหรือกระทำสิ่งที่เป็นภัยต่อตนเอง"?', '["ปลาหมอตายเพราะปาก","ช้างตายทั้งตัวเอาใบบัวมาปิด","ไก่เห็นตีนงู งูเห็นนมไก่","ขี่ช้างจับตั๊กแตน"]'::jsonb, 0, '"ปลาหมอตายเพราะปาก" หมายถึง คนที่พูดพล่อยจนได้รับอันตรายหรือความเดือดร้อนถึงตัว'),
('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/7] การใช้สำนวนเปรียบเทียบ', 'easy', 'mcq', 'คนที่ทำความดีโดยไม่ต้องการให้ใครชมเชย ตรงกับสำนวนใด?', '["ปิดทองหลังพระ","กบในกะลาครอบ","น้ำซึมบ่อทราย","เข็นครกขึ้นภูเขา"]'::jsonb, 0, '"ปิดทองหลังพระ" หมายถึง การทำความดีโดยไม่ป่าวประกาศหรือหวังชื่อเสียงลาภยศ'),
('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/1] คำที่มีเครื่องหมายทัณฑฆาต (การันต์)', 'easy', 'mcq', 'คำในข้อใดเขียนสะกดการันต์ถูกต้อง?', '["สัตว์แพทย์","สัตย์แพทย์","สัตวแพทย์","สัตถ์แพทย์"]'::jsonb, 2, '"สัตวแพทย์" (สัต-ตะ-วะ-แพด) เขียนโดยไม่มีไม้ทัณฑฆาตที่ ว เพื่อให้ออกเสียงเชื่อมสมาส'),
('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/1] คำพ้องรูปและคำพ้องเสียง', 'medium', 'mcq', 'คำว่า "กานต์, กาล, การ, กาฬ" จัดเป็นคำประเภทใด?', '["คำพ้องรูป","คำพ้องเสียง","คำพ้องความหมาย","คำซ้อน"]'::jsonb, 1, 'ออกเสียงว่า "กาน" เหมือนกันทุกคำ แต่เขียนต่างรูปและมีความหมายต่างกัน จึงเป็น "คำพ้องเสียง"'),
('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/1] คำพ้องรูป', 'hard', 'mcq', '"เพลา" สามารถอ่านออกเสียงได้ 2 แบบที่มีความหมายต่างกัน คือข้อใด?', '["เพ-ลา (เวลา) และ เพลา (แกนดุมล้อ/เบาลง)","เพ-ลา (ต้นไม้) และ เพ-ลา (แม่น้ำ)","เพลา (ลม) และ เพลา (ไฟ)","เพ-ลา (ความสุข) และ เพลา (ความเศร้า)"]'::jsonb, 0, '"เพลา" เขียนเหมือนกันแต่อ่านได้สองแบบ: เพ-ลา หมายถึง กาลเวลา และ เพลา หมายถึง แกนล้อหรือเบาลง'),
('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/5] การใช้เครื่องหมายวรรคตอน', 'easy', 'mcq', 'เครื่องหมาย "ไม้ยมก" (ๆ) ใช้ในกรณีใด?', '["ใช้แสดงคำตกหล่น","ใช้เขียนซ้ำคำหรือวลี","ใช้แสดงความตกใจ","ใช้ละข้อความตอนท้าย"]'::jsonb, 1, 'ไม้ยมก (ๆ) ใช้เขียนไว้หลังคำ วลี หรือประโยคเพื่อให้อ่านซ้ำคำ เช่น เด็กๆ, นานๆ ครั้ง'),
('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/5] การใช้เครื่องหมายอัศเจรีย์ (!)', 'easy', 'mcq', 'เครื่องหมายอัศเจรีย์ (!) นิยมใช้หลังคำชนิดใด?', '["คำนาม","คำอุทานแสดงอารมณ์","คำสรรพนาม","คำสันธาน"]'::jsonb, 1, 'เครื่องหมายอัศเจรีย์ (!) วางไว้หลังคำอุทานบอกอาการ เช่น ไชโย! โอ๊ย! คุณพระช่วย!'),
('ภาษาไทย', 'ป.4', '[ท 5.1 ป.4/1] วรรณคดีเรื่อง พระอภัยมณี (ตอน กำเนิดสุดสาคร)', 'easy', 'mcq', 'สุดสาครเป็นโอรสของพระอภัยมณีกับใคร?', '["นางผีเสื้อสมุทร","นางสุวรรณมาลี","นางเงือก","นางละเวงวัณฬา"]'::jsonb, 2, 'สุดสาครเป็นบุตรของพระอภัยมณีกับนางเงือกที่ช่วยพาพระอภัยมณีหนีนางผีเสื้อสมุทรไปยังเกาะแก้วพิสดาร'),
('ภาษาไทย', 'ป.4', '[ท 5.1 ป.4/1] สัตว์พาหนะคู่ใจของสุดสาคร', 'easy', 'mcq', 'ม้านิลมังกร พาหนะของสุดสาคร มีลักษณะผสมระหว่างสัตว์ชนิดใด?', '["หัวเป็นม้า ตัวเป็นช้าง","หัวเป็นมังกร ตัวเป็นม้า หางเป็นนาค ลำตัวดั่งนิลกาฬ","หัวเป็นสิงโต ตัวเป็นม้า","หัวเป็นพญานาค ตัวเป็นนกอินทรี"]'::jsonb, 1, 'ม้านิลมังกรมีเขี้ยวเป็นเพชร เกล็ดเป็นนิล ลิ้นเป็นปาน หัวเป็นมังกร ตัวเป็นม้า หางเป็นนาค ดำน้ำได้ วิ่งบนผิวน้ำได้'),
('ภาษาไทย', 'ป.4', '[ท 5.1 ป.4/2] ข้อคิดจากเรื่อง พระอภัยมณี ตอน กำเนิดสุดสาคร', 'medium', 'mcq', 'กลอนบทที่ว่า "แล้วสอนว่าอย่าไว้ใจมนุษย์ มันแสนสุดลึกล้ำเหลือกำหนด..." ให้ข้อคิดเตือนใจเรื่องใด?', '["อย่าหลงเชื่อใจใครง่ายๆ เพราะจิตใจคนยากแท้หยั่งถึง","มนุษย์ทุกคนเป็นคนชั่วร้าย","ไม่ควรพูดคุยกับคนแปลกหน้าตลอดชีวิต","ให้ระวังอันตรายจากสัตว์ป่า"]'::jsonb, 0, 'พระโยคีสอนสุดสาครหลังถูกชีเปลือยหลอกผลักตกเหว สอนว่าจิตใจของมนุษย์นั้นคดเคี้ยวยิ่งกว่าสิ่งใด ไม่ควรไว้ใจคนง่ายเกินไป'),
('ภาษาไทย', 'ป.4', '[ท 5.1 ป.4/1] วรรณกรรมพื้นบ้านและนิทานไทย', 'medium', 'mcq', 'นิทานเรื่อง "น้ำผึ้งหยดเดียว" มีสาเหตุเริ่มต้นเกิดจากสิ่งใด?', '["สงครามแย่งชิงเมือง","เด็กทำน้ำผึ้งหกหยดเดียวลงบนพื้นดิน","มดกับปลวกแย่งอาหารกัน","สุนัขกัดกับแมว"]'::jsonb, 1, 'เรื่องเริ่มจากเด็กทำน้ำผึ้งหยดลงพื้น มดแมลงวันตอม จิ้งจกมากิน แมวตะครุบจิ้งจก หมากัดแมว คนตีกันจนลุกลามใหญ่โต'),
('ภาษาไทย', 'ป.4', '[ท 5.1 ป.4/2] ข้อคิดจากนิทานเรื่อง น้ำผึ้งหยดเดียว', 'medium', 'mcq', 'ข้อคิดหลักที่ได้จากเรื่อง "น้ำผึ้งหยดเดียว" คือข้อใด?', '["น้ำผึ้งเป็นอาหารที่มีคุณค่าทางยา","เรื่องเล็กน้อยหากไม่ระงับอารมณ์อาจลุกลามเป็นเรื่องใหญ่โต","สัตว์เลี้ยงนำพาความเดือดร้อนมาสู่เจ้าของเสมอ","ไม่ควรรับประทานน้ำผึ้งในที่สาธารณะ"]'::jsonb, 1, 'สอนให้มีสติยับยั้งชั่งใจ เรื่องเพียงเล็กน้อยหากขาดสติอาจบานปลายกลายเป็นความเสียหายใหญ่หลวงได้'),
('ภาษาไทย', 'ป.4', '[ท 5.1 ป.4/3] เพลงพื้นบ้านและบทกล่อมเด็ก', 'easy', 'mcq', 'บทเพลงร้องเล่น "รีรีข้าวสาร" มีคุณค่าต่อเด็กในด้านใด?', '["สอนการคำนวณราคาสินค้า","สร้างความสนุกสนานและฝึกความสามัคคีในการละเล่นพื้นบ้าน","ฝึกการขับขี่พาหนะ","สอนวิธีการทำนาปลูกข้าวแบบโบราณ"]'::jsonb, 1, 'การละเล่นรีรีข้าวสารเป็นการละเล่นไทยที่ให้ความสนุกสนาน ฝึกการเคลื่อนไหวร่างกาย และสร้างความสัมพันธ์ที่ดีในหมู่เพื่อน'),
('ภาษาไทย', 'ป.4', '[ท 5.1 ป.4/4] บทอาขยานบทหลัก: พฤษภกาสร', 'hard', 'mcq', '"พฤษภกาสร อีกกุญชรอันปลดปลง..." คำว่า "พฤษภ" และ "กาสร" หมายถึงสัตว์ชนิดใดตามลำดับ?', '["วัว และ ควาย","ช้าง และ ม้า","เสือ และ สิงโต","นก และ ปลา"]'::jsonb, 0, 'พฤษภ หมายถึง วัว, กาสร หมายถึง ควาย, กุญชร หมายถึง ช้าง บทนี้สอนเรื่องความดีคงอยู่แม้ความตายมาถึง'),
('ภาษาไทย', 'ป.4', '[ท 5.1 ป.4/4] คุณค่าของบทอาขยาน พฤษภกาสร', 'medium', 'mcq', 'วรรคทอง "อินทรีย์ร่วงทบทับ สูญสิ้นสุดเสน่หา แต่ชั่วดีประดับ คงไว้ในโลกา" มีความหมายตรงกับข้อใด?', '["เมื่อมนุษย์ตายไป มีเพียงความดีและความชั่วเท่านั้นที่ยังคงหลงเหลือให้คนจดจำ","ร่างกายมนุษย์ไม่มีวันเน่าเปื่อย","ความรักเป็นสิ่งที่ไม่ยั่งยืน","สัตว์มีค่ามากกว่ามนุษย์"]'::jsonb, 0, 'บทนี้เปรียบเทียบว่าสัตว์เมื่อตายยังมีเขาและงา แต่มนุษย์เมื่อสิ้นชีวิตจะเหลือเพียงชื่อเสียงความดีความชั่วที่ทำไว้'),
('ภาษาไทย', 'ป.4', '[ท 5.1 ป.4/1] วรรณคดีเรื่อง บทละครเรื่อง เงาะป่า', 'medium', 'mcq', 'ตัวละครเอกที่เป็นเด็กชาวป่า (เงาะซาไก) ในเรื่องเงาะป่าชื่อว่าอะไร?', '["คนัง","สุดสาคร","สังข์ทอง","สินสมุทร"]'::jsonb, 0, 'พระบาทสมเด็จพระจุลจอมเกล้าเจ้าอยู่หัว (ร.5) ทรงรับเด็กชาวป่าชื่อ "คนัง" มาชุบเลี้ยง และทรงพระราชนิพนธ์เรื่องเงาะป่า'),
('ภาษาไทย', 'ป.4', '[ท 5.1 ป.4/2] การนำความรู้จากวรรณคดีไปใช้ในชีวิตจริง', 'easy', 'mcq', 'การอ่านวรรณคดีไทยมีประโยชน์อย่างไรต่อตัวนักเรียนมากที่สุด?', '["ทำให้จดจำเนื้อเรื่องไปเล่นเกม","ช่วยให้เข้าใจภาษา วัฒนธรรม ได้ข้อคิดสอนใจและสุนทรียภาพ","ช่วยประหยัดค่าใช้จ่ายในบ้าน","ทำให้มีอายุยืนยาวกว่าผู้อื่น"]'::jsonb, 1, 'วรรณคดีไทยช่วยปลูกฝังคุณธรรม ค่านิยมอันดีงาม ความซาบซึ้งในภาษาไทย และข้อคิดในการดำเนินชีวิต');
INSERT INTO public.exam_sets (title, subject, grade, questions, time_limit_minutes, pass_threshold_pct, pin_code, is_active)
